import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def generate_complex_pairs_m(max_m):
    m_values = set()

    # Iterate over the GCD g >= 2
    g = 2
    while True:
        g_squared = g * g
        if g_squared > max_m:
            break

        # Iterate over primitive representations x', y' such that g^2 (x'^2 + y'^2) <= max_m
        # We assume x' < y' for unique pairs
        x_prime = 1
        while True:
            y_prime_min = x_prime + 1

            # Upper bound for y_prime: y'^2 <= max_m/g^2 - x'^2
            y_prime_sq_limit = max_m / g_squared - x_prime * x_prime
            if y_prime_sq_limit < y_prime_min**2:
                break
            y_prime_max = int(math.sqrt(y_prime_sq_limit))

            y_prime = y_prime_min
            while y_prime <= y_prime_max:
                if gcd(x_prime, y_prime) == 1:
                    m = g_squared * (x_prime**2 + y_prime**2)
                    # m should be <= max_m due to calculation of y_prime_max, but safety check
                    if m <= max_m:
                        m_values.add(m)
                y_prime += 1

            x_prime += 1

    return sorted(list(m_values))

