import math

def find_good_numbers(max_y):
    good_numbers = set()
    # Iterate over pairs (x, y) such that 1 <= x < y <= max_y
    for x in range(1, max_y + 1):
        for y in range(x + 1, max_y + 1):
            if math.gcd(x, y) > 1:
                m = x*x + y*y
                good_numbers.add(m)
    return sorted(list(good_numbers))

