import math

def is_primitive_sum_of_squares(x, y):
    """Checks if x^2 + y^2 is a primitive sum of two squares (i.e., gcd(x, y) = 1)."""
    if x <= 0 or y <= 0:
        return False
    return math.gcd(x, y) == 1

def generate_primitive_sums_of_squares(max_s):
    """Generates primitive sums S = x^2 + y^2 up to max_s, with x < y."""
    S_values = set()
    # We need y^2 < max_s, so y < sqrt(max_s)
    max_y = int(math.sqrt(max_s))

    for y in range(2, max_y + 1):
        for x in range(1, y):
            if is_primitive_sum_of_squares(x, y):
                s = x**2 + y**2
                if s <= max_s:
                    S_values.add(s)

    return sorted(list(S_values))

def solve_good_numbers_extended():
    # Search bounds: Increase S significantly.
    S_list = generate_primitive_sums_of_squares(300) 

    all_m = []

    # We must cover enough territory to find the 20th element reliably.
    # Since m_20 was 208 previously, the required range is likely close to the previous one.
